"""Report rendering.

Approach B (composition): each format is a plain function registered in
``_REGISTRY`` via the ``@register`` decorator. Shared behaviour lives in
small helper functions that the renderers call. There is no class hierarchy.
"""

from __future__ import annotations

from typing import Callable

Renderer = Callable[[dict], str]

_REGISTRY: dict[str, Renderer] = {}


class UnknownFormat(Exception):
    """Raised when ``render`` is asked for a format that is not registered."""


def register(name: str) -> Callable[[Renderer], Renderer]:
    """Register ``func`` as the renderer for format ``name``."""

    def decorator(func: Renderer) -> Renderer:
        _REGISTRY[name] = func
        return func

    return decorator


def available_formats() -> list[str]:
    return sorted(_REGISTRY)


def render(report: dict, fmt: str) -> str:
    try:
        renderer = _REGISTRY[fmt]
    except KeyError:
        raise UnknownFormat(
            f"unknown format {fmt!r}; available: {', '.join(available_formats())}"
        ) from None
    return renderer(report)


# --- shared helpers ---------------------------------------------------------


def _cells(row: list) -> list[str]:
    return [str(cell) for cell in row]


def _document(header: list[str], body: list[str]) -> str:
    """Join header, a blank line, and body lines into the final string."""
    return "\n".join([*header, "", *body])


# --- renderers --------------------------------------------------------------


@register("text")
def render_text(report: dict) -> str:
    header = [str(report["title"])]
    body = ["  ".join(_cells(row)) for row in report["rows"]]
    return _document(header, body)


@register("markdown")
def render_markdown(report: dict) -> str:
    def pipe_row(cells: list[str]) -> str:
        return "| " + " | ".join(cells) + " |"

    columns = _cells(report["columns"])
    header = [f"# {report['title']}"]
    body = [
        pipe_row(columns),
        "|" + "---|" * len(columns),
        *(pipe_row(_cells(row)) for row in report["rows"]),
    ]
    return _document(header, body)
EOF
